<template><Card class="s3-manager"><header class="header"><div><h2>商城订单</h2><p>按合单分页，显示命中条件的子单；展开查看该合单的全部真实子单。</p></div></header><Form inline class="query" @submit.native.prevent="search"><FormItem label="订单 / 店铺 / 商品"><Input v-model="q" maxlength="64" clearable placeholder="输入订单号、店名或商品名称" @on-enter="search"/></FormItem><FormItem label="履约方式"><Select v-model="method" clearable><Option v-for="v in methods" :key="v" :value="v">{{label(v)}}</Option></Select></FormItem><FormItem label="付款状态"><Select v-model="paymentStatus" clearable><Option v-for="v in payments" :key="v" :value="v">{{label(v)}}</Option></Select></FormItem><FormItem label="履约状态"><Select v-model="phase" clearable><Option v-for="v in phases" :key="v" :value="v">{{label(v)}}</Option></Select></FormItem><FormItem label="创建日期（北京）"><DatePicker v-model="dates" type="daterange" placeholder="选择开始和结束日期" style="width:240px"/></FormItem><Button type="primary" :loading="loading" @click="search">查询</Button><Button @click="reset">重置</Button></Form><Alert v-if="error" type="error" show-icon>{{error}} <Button type="text" @click="load">重新读取</Button></Alert><div v-if="!error" class="table-scroll"><Table :columns="columns" :data="records" :loading="loading" :row-key="true" no-data-text="当前条件下没有订单"><template slot="identity" slot-scope="{row}"><strong>合单 {{row.tradeSn}}</strong><p>{{row.storeName}}</p><p class="meta">命中子单 {{row.orderSn}}</p></template><template slot="items" slot-scope="{row}"><p v-for="i in row.items" :key="i.skuId">{{i.name}} ×{{i.quantity}}</p></template><template slot="payment" slot-scope="{row}"><Tag :color="row.trustedPaid?'green':'orange'">{{label(row.paymentStatus)}}</Tag><p>{{row.paidAmountCent==null?'子单实付待核实':'命中子单 '+money(row.paidAmountCent)}}</p><p class="meta">{{date(row.paidAt)}}</p></template><template slot="fulfillment" slot-scope="{row}"><p>{{label(row.method)}}</p><Tag :color="row.blockedReason?'orange':row.phase==='COMPLETED'?'green':'blue'">{{label(row.phase)}}</Tag><p v-if="row.blockedReason" class="warning">交接或操作条件待核实</p></template><template slot="created" slot-scope="{row}">{{date(row.createdAt)}}</template><template slot="operation" slot-scope="{row}"><Button size="small" @click="open(row.orderId)">查看详情</Button></template></Table></div><Page v-if="!error" :total="total" :current="page" :page-size="20" show-total @on-change="turn"/></Card></template>
<script>
import {stage3Read} from '@/api/stage3';import {managerSession} from '@/libs/manager-session';import {money,date,label,day,range,restoreDates} from './presentation.cjs';
const keys=['q','method','paymentStatus','phase'];
export default{
 data(){const q=this.$route.query;return {q:q.q||'',method:q.method||'',paymentStatus:q.paymentStatus||'',phase:q.phase||'',dates:restoreDates(q),page:Number(q.page)||1,records:[],total:0,error:'',loading:false,ticket:0,
 methods:['MERCHANT_DELIVERY','EXPRESS','COMMUNITY_PICKUP','STORE_REDEMPTION'],payments:['NOT_STARTED','UNPAID','UNKNOWN','SUCCEEDED','CLOSED'],phases:['WAIT_PREPARE','WAIT_DISPATCH','WAIT_SHIP','DELIVERING','DELIVERED','SHIPPED','WAIT_PICKUP','WAIT_VERIFY','COMPLETED','BLOCKED'],
 columns:[{type:'expand',width:44,render:(h,{row})=>h('div',{class:'related'},[(row.relatedOrders||[row]).map(child=>h('div',{class:'related-row'},[h('strong',child.storeName),h('span',child.orderSn+' · '+label(child.method)+' · '+label(child.phase)),h('span',money(child.amountCent)),h('Button',{props:{size:'small'},on:{click:()=>this.open(child.orderId)}},'查看子单')]))])},{title:'合单 / 命中子单',slot:'identity',minWidth:245},{title:'商品',slot:'items',minWidth:210},{title:'付款事实',slot:'payment',minWidth:195},{title:'方式 / 履约',slot:'fulfillment',minWidth:175},{title:'创建时间',slot:'created',minWidth:175},{title:'操作',slot:'operation',width:110}]}},
 mounted(){this.load()},beforeDestroy(){this.ticket++},
 methods:{money,date,label,query(){const params={pageNumber:this.page,pageSize:20};for(const key of keys)if(this[key])params[key]=this[key];Object.assign(params,range(this.dates));return params},
 async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const value=await stage3Read('/trades',this.query());if(ticket===this.ticket&&managerSession.sameSession(owner)){this.records=value.records;this.total=value.total}}catch(e){if(ticket===this.ticket){this.records=[];this.total=0;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},
 remember(){const query={page:String(this.page)};for(const key of keys)if(this[key])query[key]=this[key];if(this.dates[0])query.fromDay=day(this.dates[0]);if(this.dates[1])query.toDay=day(this.dates[1]);this.$router.replace({path:'/s3/orders',query}).catch(()=>{})},search(){this.page=1;this.remember();this.load()},reset(){for(const key of keys)this[key]='';this.dates=[];this.search()},turn(page){this.page=page;this.remember();this.load()},open(id){this.$router.push({path:'/s3/orders/'+id,query:this.$route.query})}}
};
</script><style lang="scss">@import './stage3.scss';</style>
